private static void connect(final SolanaRpcWebsocket webSocket) {
  final var attempt = webSocket.connect();
  if (attempt != null) {
    attempt.whenComplete((_, throwable) -> {
      if (throwable != null) {
        System.err.println("Connect failed, retrying: " + throwable);
        connect(webSocket);
      }
    });
  }
}
